/// <summary>
/// Abstract base class for consolidating MET Customer MDF Calculation Transactions
/// </summary>
public abstract class METCustomerMDFConsolidation
{
    CustAccount custAccount;
    InventSiteId siteId;
    InventLocationId warehouse;

}

Method.Source:
/// <summary>
/// Abstract method to get the query for fetching METCustomerMDFCalculationTrans records
/// </summary>
/// <returns>Query</returns>
abstract Query getQuery()
{

}

/// <summary>
/// Update the query to filter by customer, site, and warehouse
/// </summary>
/// <param name = "_query">Query</param>
/// <returns>Query</returns>
Query updateQuery(Query _query)
{
    QueryBuildDataSource qbds = _query.dataSourceTable(tableNum(METCustomerMDFCalculationTrans));

    qbds.addRange(fieldNum(METCustomerMDFCalculationTrans, CustAccount)).value(custAccount);
    qbds.addRange(fieldNum(METCustomerMDFCalculationTrans, SiteId)).value(siteId);
    qbds.addRange(fieldNum(METCustomerMDFCalculationTrans, Warehouse)).value(warehouse);

    return _query;
}

/// <summary>
/// Process the consolidation of MDF calculation transactions
/// </summary>
void process()
{
    #OCCRetryCount

    try
    {
        ttsbegin;

        Query query = this.getQuery();
        query = this.updateQuery(query);

        QueryRun queryRun = new QueryRun(query);

        while(queryRun.next())
        {
            METCustomerMDFCalculationTrans calculationTransSum = queryRun.get(tableNum(METCustomerMDFCalculationTrans));

            this.processCalculationTransSum(calculationTransSum);
        }

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }
}

/// <summary>
/// Process a single MDF calculation transaction summary
/// </summary>
/// <param name = "_calculationTransSum">METCustomerMDFCalculationTrans</param>
void processCalculationTransSum(METCustomerMDFCalculationTrans _calculationTransSum)
{
    ttsbegin;

    RefRecId consolidationTableRecId = this.createConsolidationTable(_calculationTransSum);

    this.updateCalculationTrans(_calculationTransSum, consolidationTableRecId);

    ttscommit;
}

/// <summary>
/// Create a consolidation table entry based on the calculation transaction summary
/// </summary>
/// <param name = "_calculationTransSum">METCustomerMDFCalculationTrans</param>
/// <returns>RefRecId</returns>
public RefRecId createConsolidationTable(METCustomerMDFCalculationTrans _calculationTransSum)
{
    METCustomerMDFConsolidationTable consolidationTableInsert;
    MetCustomerMdfSetupTable customerMdfSetupTable = MetCustomerMdfSetupTable::findRecId(_calculationTransSum.CustomerMDFSetupTable);
    MetCustomerMdfTable customerMdfTable = MetCustomerMdfTable::findRecId(customerMdfSetupTable.RefRecId);

    consolidationTableInsert.CustAccount = _calculationTransSum.CustAccount;
    consolidationTableInsert.ConsolidationMethod = customerMdfTable.ConsolidationMethodEDT;
    consolidationTableInsert.ShipDate = _calculationTransSum.ShipDate;
    consolidationTableInsert.ShipmentId = _calculationTransSum.ShipmentId;
    consolidationTableInsert.ApplicationMethod = customerMdfTable.ApplicationMethodEDT;
    consolidationTableInsert.Amount = _calculationTransSum.Amount;
    consolidationTableInsert.Qty = _calculationTransSum.Qty;
    consolidationTableInsert.DeliveryFee = _calculationTransSum.DeliveryFee;
    consolidationTableInsert.CustomerMDFSetupTable = _calculationTransSum.CustomerMDFSetupTable;
    consolidationTableInsert.MDF = this.calcMDF(_calculationTransSum);
    consolidationTableInsert.insert();

    return consolidationTableInsert.RecId;
}

/// <summary>
/// Calculate the MDF based on the calculation transaction summary and the associated setup
/// </summary>
/// <param name = "_calculationTransSum">METCustomerMDFCalculationTrans</param>
/// <returns>Amount</returns>
Amount calcMDF(METCustomerMDFCalculationTrans _calculationTransSum)
{
    Amount ret;

    MetCustomerMdfSetupTable customerMdfSetupTable = MetCustomerMdfSetupTable::findRecId(_calculationTransSum.CustomerMDFSetupTable);

    switch (customerMdfSetupTable.DeliveryChargeType)
    {
        case METDeliveryChargeType::CartonTotalCaseFee:
            if (_calculationTransSum.Qty < customerMdfSetupTable.ThresholdValue)
            {
                ret = _calculationTransSum.Qty * customerMdfSetupTable.MinimumDeliveryFee;
            }
            break;
        case METDeliveryChargeType::CartonTotalFlatFee:
            if (_calculationTransSum.Qty < customerMdfSetupTable.ThresholdValue)
            {
                ret = customerMdfSetupTable.MinimumDeliveryFee;
            }
            break;
        case METDeliveryChargeType::TotalDeliveryFees:
            if (_calculationTransSum.DeliveryFee < customerMdfSetupTable.MinimumDeliveryFee)
            {
                ret = customerMdfSetupTable.MinimumDeliveryFee - _calculationTransSum.DeliveryFee;
            }
            break;
        case METDeliveryChargeType::TotalInvoiceAmount:
            if (_calculationTransSum.Amount < customerMdfSetupTable.ThresholdValue)
            {
                ret = customerMdfSetupTable.MinimumDeliveryFee;
            }
            break;
    }

    return ret;
}

/// <summary>
/// Abstract method to update the calculation transactions with the consolidation reference
/// </summary>
/// <param name = "_calculationTransSum">METCustomerMDFCalculationTrans</param>
/// <param name = "_consolidationTableRecId">RefRecId</param>
abstract void updateCalculationTrans(METCustomerMDFCalculationTrans _calculationTransSum, RefRecId _consolidationTableRecId)
{

}

/// <summary>
/// Parameter method for CustAccount
/// </summary>
/// <param name = "_custAccount">CustAccount</param>
/// <returns>CustAccount</returns>
public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;

    return custAccount;
}

/// <summary>
/// Parameter method for SiteId
/// </summary>
/// <param name = "_siteId">InventSiteId</param>
/// <returns>InventSiteId</returns>
public InventSiteId parmSiteId(InventSiteId _siteId = siteId)
{
    siteId = _siteId;

    return siteId;
}

/// <summary>
/// Parameter method for Warehouse
/// </summary>
/// <param name = "_warehouse">InventLocationId</param>
/// <returns>InventLocationId</returns>
public InventLocationId parmWarehouse(InventLocationId _warehouse = warehouse)
{
    warehouse = _warehouse;

    return warehouse;
}
